rules.check:
const text = String(row.body ?? "").trim();
if (!text) return "Write something before you post.";
if (text.length > 4000) return "Keep comments under 4,000 characters.";
return true;

if (!row.parent_id) return true;
const r = await ctx.db.query("select subject_id from comment where id = $1", [row.parent_id]);
const rows = Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? [];
if (!rows[0]) return "That comment no longer exists.";
return String(rows[0].subject_id) === String(row.subject_id) || "A reply belongs to the same thread as the comment it answers.";

const r = await ctx.db.query('select "{{param.org_field}}" as org from "{{param.attach_to}}" where id = $1', [row.subject_id]);
const rows = Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? [];
if (!rows[0]) return "You can't comment on that.";
return String(rows[0].org ?? "") === String(row.organisation_id ?? "") || "A comment belongs to the organisation of what it's about.";

do.code:
const author = await ctx.db.get("{{param.author_role}}", String(row["author_id"] ?? ""));
const name = author ? String(author["{{param.author_role.label_field}}"] ?? "Someone") : "Someone";
const text = String(row["body"] ?? "");
const snippet = text.length > 140 ? `${text.slice(0, 137)}...` : text;
const told = new Set<string>([String(row["author_id"] ?? "")]);
for (const id of String(row["mentions"] ?? "").split(",").map((s) => s.trim()).filter(Boolean)) {
  if (told.has(id)) continue;
  told.add(id);
  const person = await ctx.db.get("{{param.author_role}}", id);
  if (person && person["user_id"]) await ctx.notify({ title: `${name} mentioned you`, body: snippet, user: String(person["user_id"]) });
}
if (row["parent_id"]) {
  const parent = await ctx.db.get("comment", String(row["parent_id"]));
  const to = parent ? String(parent["author_id"] ?? "") : "";
  if (to && !told.has(to)) {
    const person = await ctx.db.get("{{param.author_role}}", to);
    if (person && person["user_id"]) await ctx.notify({ title: `${name} replied to your comment`, body: snippet, user: String(person["user_id"]) });
  }
}
